 SELECT ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    ( SELECT btrim((dmn_provincie_code.description)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie_desc,
    s.subsidie_jaar,
    ( SELECT btrim((dmn_status_plan.code)::text) AS btrim
           FROM masterdata.dmn_status_plan
          WHERE (dmn_status_plan.id = s.status_id)) AS status,
    ( SELECT btrim((dmn_status_plan.description)::text) AS btrim
           FROM masterdata.dmn_status_plan
          WHERE (dmn_status_plan.id = s.status_id)) AS status_desc,
    btrim((p.identificatie)::text) AS identificatie,
    p.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    p.datum_vaststelling,
    btrim((p.plan_naam)::text) AS plan_naam,
    ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = p.plan_eigenaar_id)) AS plan_eigenaar,
    ( SELECT btrim((dmn_provincie_code.description)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = p.plan_eigenaar_id)) AS plan_eigenaar_desc,
    btrim(p.plan_verwijzing) AS plan_verwijzing,
    ( SELECT btrim((dmn_status_beheer_gebied.code)::text) AS btrim
           FROM masterdata.dmn_status_beheer_gebied
          WHERE (dmn_status_beheer_gebied.id = p.beheer_gebied_status_id)) AS beheer_gebied_status,
    ( SELECT btrim((dmn_status_beheer_gebied.description)::text) AS btrim
           FROM masterdata.dmn_status_beheer_gebied
          WHERE (dmn_status_beheer_gebied.id = p.beheer_gebied_status_id)) AS beheer_gebied_status_desc,
    ( SELECT btrim((dmn_status_beheer_gebied_ambitie.code)::text) AS btrim
           FROM masterdata.dmn_status_beheer_gebied_ambitie
          WHERE (dmn_status_beheer_gebied_ambitie.id = p.beheer_gebied_ambitie_status_id)) AS beheer_gebied_ambitie_status,
    ( SELECT btrim((dmn_status_beheer_gebied_ambitie.description)::text) AS btrim
           FROM masterdata.dmn_status_beheer_gebied_ambitie
          WHERE (dmn_status_beheer_gebied_ambitie.id = p.beheer_gebied_ambitie_status_id)) AS beheer_gebied_ambitie_status_desc,
    ( SELECT btrim((dmn_status_bijzonder_gebied.code)::text) AS btrim
           FROM masterdata.dmn_status_bijzonder_gebied
          WHERE (dmn_status_bijzonder_gebied.id = p.bijzonder_gebied_status_id)) AS bijzonder_gebied_status,
    ( SELECT btrim((dmn_status_bijzonder_gebied.description)::text) AS btrim
           FROM masterdata.dmn_status_bijzonder_gebied
          WHERE (dmn_status_bijzonder_gebied.id = p.bijzonder_gebied_status_id)) AS bijzonder_gebied_status_desc,
    ( SELECT btrim((dmn_status_deel_gebied.code)::text) AS btrim
           FROM masterdata.dmn_status_deel_gebied
          WHERE (dmn_status_deel_gebied.id = p.deel_gebied_status_id)) AS deel_gebied_status,
    ( SELECT btrim((dmn_status_deel_gebied.description)::text) AS btrim
           FROM masterdata.dmn_status_deel_gebied
          WHERE (dmn_status_deel_gebied.id = p.deel_gebied_status_id)) AS deel_gebied_status_desc,
    ( SELECT btrim((dmn_status_zoek_gebied_landschap.code)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_landschap
          WHERE (dmn_status_zoek_gebied_landschap.id = p.zoek_gebied_landschap_status_id)) AS zoek_gebied_landschap_status,
    ( SELECT btrim((dmn_status_zoek_gebied_landschap.description)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_landschap
          WHERE (dmn_status_zoek_gebied_landschap.id = p.zoek_gebied_landschap_status_id)) AS zoek_gebied_landschap_status_desc,
    ( SELECT btrim((dmn_status_zoek_gebied_agrarisch.code)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_agrarisch
          WHERE (dmn_status_zoek_gebied_agrarisch.id = p.zoek_gebied_agrarisch_status_id)) AS zoek_gebied_agrarisch_status,
    ( SELECT btrim((dmn_status_zoek_gebied_agrarisch.description)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_agrarisch
          WHERE (dmn_status_zoek_gebied_agrarisch.id = p.zoek_gebied_agrarisch_status_id)) AS zoek_gebied_agrarisch_status_desc,
    ( SELECT btrim((dmn_status_zoek_gebied_water.code)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_water
          WHERE (dmn_status_zoek_gebied_water.id = p.zoek_gebied_water_status_id)) AS zoek_gebied_water_status,
    ( SELECT btrim((dmn_status_zoek_gebied_water.description)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_water
          WHERE (dmn_status_zoek_gebied_water.id = p.zoek_gebied_water_status_id)) AS zoek_gebied_water_status_desc,
    ( SELECT btrim((dmn_status_zoek_gebied_klimaat.code)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_klimaat
          WHERE (dmn_status_zoek_gebied_klimaat.id = p.zoek_gebied_klimaat_status_id)) AS zoek_gebied_klimaat_status,
	( SELECT btrim((dmn_status_zoek_gebied_klimaat.description)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_klimaat
          WHERE (dmn_status_zoek_gebied_klimaat.id = p.zoek_gebied_klimaat_status_id)) AS zoek_gebied_klimaat_status_desc,		  
    ((( SELECT pr.value
           FROM masterdata.parameters pr
          WHERE ((pr.name)::text = 'DrupalArchiveURL'::text)))::text || (p.document_link)::text) AS document_link
   FROM (imna.vm_prov_year_status_natuur_beheer_plan s
     JOIN imna.natuur_beheer_plan p ON ((p.id = s.plan_id)));
;

CREATE OR REPLACE VIEW imna.v_gs_zoek_gebied_agrarisch AS 
 SELECT ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    ( SELECT btrim((dmn_provincie_code.description)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie_desc,
    s.subsidie_jaar,
    ( SELECT btrim((dmn_status_zoek_gebied_agrarisch.code)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_agrarisch
          WHERE (dmn_status_zoek_gebied_agrarisch.id = s.status_id)) AS status,
    ( SELECT btrim((dmn_status_zoek_gebied_agrarisch.description)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_agrarisch
          WHERE (dmn_status_zoek_gebied_agrarisch.id = s.status_id)) AS status_desc,
    a.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    btrim((a.identificatie)::text) AS identificatie,
    a.begin_tijd,
    a.eind_tijd,
    ( SELECT btrim((dmn_natuur_type_agrarisch.code)::text) AS btrim
           FROM masterdata.dmn_natuur_type_agrarisch
          WHERE (dmn_natuur_type_agrarisch.id = a.agrarisch_natuur_type_id)) AS agrarisch_natuur_type,
    ( SELECT btrim((dmn_natuur_type_agrarisch.description)::text) AS btrim
           FROM masterdata.dmn_natuur_type_agrarisch
          WHERE (dmn_natuur_type_agrarisch.id = a.agrarisch_natuur_type_id)) AS agrarisch_natuur_type_desc,
    btrim((a.naam)::text) AS naam,
	CASE
        WHEN (a.deelgebied_id IS NOT NULL) 
			THEN ( SELECT btrim((dmn_deelgebied.code)::text) AS btrim
					 FROM masterdata.dmn_deelgebied
					WHERE (dmn_deelgebied.id = a.deelgebied_id))
			ELSE NULL::text
    END AS deel_gebied_code,
	CASE
        WHEN (a.deelgebied_id IS NOT NULL) 
			THEN ( SELECT btrim((dmn_deelgebied.description)::text) AS btrim
					 FROM masterdata.dmn_deelgebied
					WHERE (dmn_deelgebied.id = a.deelgebied_id))
			ELSE btrim((a.deel_gebied_naam)::text) 
    END AS deel_gebied_naam,
    ( SELECT string_agg((((d.code)::text || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_functies_agrarisch fun
             JOIN masterdata.dmn_beheer_functie d ON ((d.id = fun.beheer_functie_id)))
          WHERE (fun.zoek_gebied_agrarisch_id = a.id)) AS toegestane_beheer_functies,
    ( SELECT string_agg((((d.code)::text || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_typen_agrarisch typ
             JOIN masterdata.dmn_beheer_type d ON ((d.id = typ.beheer_type_id)))
          WHERE (typ.zoek_gebied_agrarisch_id = a.id)) AS toegestane_beheer_typen,
    ((( SELECT pr.value
           FROM masterdata.parameters pr
          WHERE ((pr.name)::text = 'DrupalArchiveURL'::text)))::text || (( SELECT natuur_beheer_plan.document_link
           FROM imna.natuur_beheer_plan
          WHERE (natuur_beheer_plan.id = s.plan_id)))::text) AS document_link,
    a.geom
   FROM (imna.vm_prov_year_status_zoek_gebied_agrarisch s
     JOIN imna.zoek_gebied_agrarisch a ON ((a.id = s.zoek_gebied_agrarisch_id)));
;

