CREATE OR REPLACE VIEW imna.v_rvo_beheer_gebied AS 
 SELECT ( SELECT dmn_provincie_code.code
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    s.subsidie_jaar,
    ( SELECT dmn_status_beheer_gebied.code
           FROM masterdata.dmn_status_beheer_gebied
          WHERE (dmn_status_beheer_gebied.id = s.status_id)) AS status,
    b.identificatie,
    b.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    b.begin_tijd,
    b.eind_tijd,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN ( SELECT dmn_beheer_type_natuur.code
               FROM masterdata.dmn_beheer_type_natuur
              WHERE (dmn_beheer_type_natuur.id = n.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN ( SELECT dmn_beheer_type_grootschaligenatuur.code
               FROM masterdata.dmn_beheer_type_grootschaligenatuur
              WHERE (dmn_beheer_type_grootschaligenatuur.id = g.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN ( SELECT dmn_beheer_type_agrarisch.code
               FROM masterdata.dmn_beheer_type_agrarisch
              WHERE (dmn_beheer_type_agrarisch.id = a.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN ( SELECT dmn_beheer_type_landschap.code
               FROM masterdata.dmn_beheer_type_landschap
              WHERE (dmn_beheer_type_landschap.id = l.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'W'::bpchar))) THEN ( SELECT dmn_beheer_type_water.code
               FROM masterdata.dmn_beheer_type_water
              WHERE (dmn_beheer_type_water.id = w.beheer_type_id))
            ELSE NULL::bpchar
        END AS beheer_type,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN n.subsidiabel
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN g.subsidiabel
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN a.subsidiabel
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN l.subsidiabel
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'W'::bpchar))) THEN a.subsidiabel
            ELSE NULL::boolean
        END AS subsidiabel,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) 
				THEN n.voorzieningenbijdrage
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) 
				THEN g.voorzieningenbijdrage
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
									     FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) 
				THEN l.voorzieningenbijdrage
            ELSE NULL::boolean
        END AS voorzieningenbijdrage,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) 
				THEN n.toezichtbijdrage
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) 
				THEN g.toezichtbijdrage
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
									     FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) 
				THEN l.toezichtbijdrage
            ELSE NULL::boolean
        END AS toezichtbijdrage,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) 
				THEN n.bijdrage_vaarland
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) 
				THEN g.bijdrage_vaarland
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
									     FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) 
				THEN l.bijdrage_vaarland
            ELSE NULL::boolean
        END AS bijdrage_vaarland,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) 
				THEN n.bijdrage_gescheperde_schaapskuddes
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) 
				THEN g.bijdrage_gescheperde_schaapskuddes
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
									     FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) 
				THEN l.bijdrage_gescheperde_schaapskuddes
            ELSE NULL::boolean
        END AS bijdrage_gescheperde_schaapskuddes,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) 
				THEN n.bijdrage_monitoring
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) 
				THEN g.bijdrage_monitoring
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
									     FROM masterdata.dmn_beheergebied_type
									    WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) 
				THEN l.bijdrage_monitoring
            ELSE NULL::boolean
        END AS bijdrage_monitoring,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN ( SELECT dmn_openstellings_bijdrage_type.code
               FROM masterdata.dmn_openstellings_bijdrage_type
              WHERE (dmn_openstellings_bijdrage_type.id = n.openstellings_bijdrage_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN ( SELECT dmn_openstellings_bijdrage_type.code
               FROM masterdata.dmn_openstellings_bijdrage_type
              WHERE (dmn_openstellings_bijdrage_type.id = g.openstellings_bijdrage_type_id))
            ELSE NULL::bpchar
        END AS openstellings_bijdrage_type,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN ( SELECT string_agg(((i.percentage || '%'::text) || (d.code)::text), ';'::text ORDER BY d.code) AS string_agg
               FROM (imna.beheer_indicatieve_verhouding_beheer_typen i
                 JOIN masterdata.dmn_beheer_type_natuur d ON ((d.id = i.beheer_type_id)))
              WHERE (i.beheer_gebied_id = g.beheer_gebied_id))
            ELSE NULL::text
        END AS indicatieve_verhouding_beheer_typen,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
               FROM (imna.beheer_toegestane_beheer_pakketten_agrarisch pak
                 JOIN masterdata.dmn_beheer_pakket d ON ((d.id = pak.beheer_pakket_id)))
              WHERE (pak.beheer_gebied_id = a.beheer_gebied_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
               FROM (imna.beheer_toegestane_beheer_pakketten_landschap pak
                 JOIN masterdata.dmn_beheer_pakket d ON ((d.id = pak.beheer_pakket_id)))
              WHERE (pak.beheer_gebied_id = l.beheer_gebied_id))
            ELSE NULL::text
        END AS toegestane_beheer_paketten,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
               FROM (imna.beheer_niet_subsidiabele_beheer_pakketten_agrarisch pak
                 JOIN masterdata.dmn_beheer_pakket d ON ((d.id = pak.beheer_pakket_id)))
              WHERE (pak.beheer_gebied_id = a.beheer_gebied_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
               FROM (imna.beheer_niet_subsidiabele_beheer_pakketten_landschap pak
                 JOIN masterdata.dmn_beheer_pakket d ON ((d.id = pak.beheer_pakket_id)))
              WHERE (pak.beheer_gebied_id = l.beheer_gebied_id))
            ELSE NULL::text
        END AS niet_subsidiabele_beheer_paketten,
    b.geom
   FROM ((((((imna.vm_prov_year_status_beheer_gebied s
     JOIN imna.beheer_gebied b ON ((b.id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_natuur n ON ((n.beheer_gebied_id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_grootschaligenatuur g ON ((g.beheer_gebied_id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_agrarisch a ON ((a.beheer_gebied_id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_landschap l ON ((l.beheer_gebied_id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_water w ON ((w.beheer_gebied_id = s.beheer_gebied_id)));
;

CREATE OR REPLACE VIEW imna.v_rvo_natuur_beheer_plan AS 
 SELECT ( SELECT dmn_provincie_code.code
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    s.subsidie_jaar,
    ( SELECT dmn_status_plan.code
           FROM masterdata.dmn_status_plan
          WHERE (dmn_status_plan.id = s.status_id)) AS status,
    p.identificatie,
    p.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    p.datum_vaststelling,
    p.plan_naam,
    ( SELECT dmn_provincie_code.code
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = p.plan_eigenaar_id)) AS plan_eigenaar,
    p.plan_verwijzing,
    ( SELECT dmn_status_beheer_gebied.code
           FROM masterdata.dmn_status_beheer_gebied
          WHERE (dmn_status_beheer_gebied.id = p.beheer_gebied_status_id)) AS beheer_gebied_status,
    ( SELECT dmn_status_beheer_gebied_ambitie.code
           FROM masterdata.dmn_status_beheer_gebied_ambitie
          WHERE (dmn_status_beheer_gebied_ambitie.id = p.beheer_gebied_ambitie_status_id)) AS beheer_gebied_ambitie_status,
    ( SELECT dmn_status_bijzonder_gebied.code
           FROM masterdata.dmn_status_bijzonder_gebied
          WHERE (dmn_status_bijzonder_gebied.id = p.bijzonder_gebied_status_id)) AS bijzonder_gebied_status,
    ( SELECT dmn_status_deel_gebied.code
           FROM masterdata.dmn_status_deel_gebied
          WHERE (dmn_status_deel_gebied.id = p.deel_gebied_status_id)) AS deel_gebied_status,
    ( SELECT dmn_status_zoek_gebied_landschap.code
           FROM masterdata.dmn_status_zoek_gebied_landschap
          WHERE (dmn_status_zoek_gebied_landschap.id = p.zoek_gebied_landschap_status_id)) AS zoek_gebied_landschap_status,
    ( SELECT dmn_status_zoek_gebied_agrarisch.code
           FROM masterdata.dmn_status_zoek_gebied_agrarisch
          WHERE (dmn_status_zoek_gebied_agrarisch.id = p.zoek_gebied_agrarisch_status_id)) AS zoek_gebied_agrarisch_status,
    ( SELECT dmn_status_zoek_gebied_water.code
           FROM masterdata.dmn_status_zoek_gebied_water
          WHERE (dmn_status_zoek_gebied_water.id = p.zoek_gebied_water_status_id)) AS zoek_gebied_water_status,
    ( SELECT dmn_status_zoek_gebied_klimaat.code
           FROM masterdata.dmn_status_zoek_gebied_klimaat
          WHERE (dmn_status_zoek_gebied_klimaat.id = p.zoek_gebied_klimaat_status_id)) AS zoek_gebied_klimaat_status,		  
    p.document_link
   FROM (imna.vm_prov_year_status_natuur_beheer_plan s
     JOIN imna.natuur_beheer_plan p ON ((p.id = s.plan_id)));
;

CREATE OR REPLACE VIEW imna.v_rvo_zoek_gebied_agrarisch AS 
 SELECT ( SELECT dmn_provincie_code.code
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    s.subsidie_jaar,
    ( SELECT dmn_status_zoek_gebied_agrarisch.code
           FROM masterdata.dmn_status_zoek_gebied_agrarisch
          WHERE (dmn_status_zoek_gebied_agrarisch.id = s.status_id)) AS status,
    a.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    a.identificatie,
    a.begin_tijd,
    a.eind_tijd,
    ( SELECT dmn_natuur_type_agrarisch.code
           FROM masterdata.dmn_natuur_type_agrarisch
          WHERE (dmn_natuur_type_agrarisch.id = a.agrarisch_natuur_type_id)) AS agrarisch_natuur_type,
    a.naam,
	CASE
        WHEN (a.deelgebied_id IS NOT NULL) 
			THEN ( SELECT btrim((dmn_deelgebied.code)::text) AS btrim
					 FROM masterdata.dmn_deelgebied
					WHERE (dmn_deelgebied.id = a.deelgebied_id))
			ELSE NULL::text
    END AS deel_gebied,
    ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_functies_agrarisch fun
             JOIN masterdata.dmn_beheer_functie d ON ((d.id = fun.beheer_functie_id)))
          WHERE (fun.zoek_gebied_agrarisch_id = a.id)) AS toegestane_beheer_functies,
    ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_typen_agrarisch typ
             JOIN masterdata.dmn_beheer_type d ON ((d.id = typ.beheer_type_id)))
          WHERE (typ.zoek_gebied_agrarisch_id = a.id)) AS toegestane_beheer_typen,
    a.geom
   FROM (imna.vm_prov_year_status_zoek_gebied_agrarisch s
     JOIN imna.zoek_gebied_agrarisch a ON ((a.id = s.zoek_gebied_agrarisch_id)));
;

CREATE OR REPLACE VIEW imna.v_rvo_zoek_gebied_klimaat AS 
 SELECT ( SELECT dmn_provincie_code.code
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    s.subsidie_jaar,
    ( SELECT dmn_status_zoek_gebied_klimaat.code
           FROM masterdata.dmn_status_zoek_gebied_klimaat
          WHERE (dmn_status_zoek_gebied_klimaat.id = s.status_id)) AS status,
    a.identificatie,
    a.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    a.begin_tijd,
    a.eind_tijd,
    ( SELECT dmn_natuur_type_klimaat.code
           FROM masterdata.dmn_natuur_type_klimaat
          WHERE (dmn_natuur_type_klimaat.id = a.klimaat_natuur_type_id)) AS klimaat_natuur_type,
    a.naam,
    CASE
        WHEN (a.deelgebied_id IS NOT NULL) 
			THEN ( SELECT btrim((dmn_deelgebied.code)::text) AS btrim
					 FROM masterdata.dmn_deelgebied
					WHERE (dmn_deelgebied.id = a.deelgebied_id))
			ELSE NULL::text
    END AS deel_gebied,
    ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_functies_klimaat fun
             JOIN masterdata.dmn_beheer_functie d ON ((d.id = fun.beheer_functie_id)))
          WHERE (fun.zoek_gebied_klimaat_id = a.id)) AS toegestane_beheer_functies,
    ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_typen_klimaat typ
             JOIN masterdata.dmn_beheer_type d ON ((d.id = typ.beheer_type_id)))
          WHERE (typ.zoek_gebied_klimaat_id = a.id)) AS toegestane_beheer_typen,
    a.geom
   FROM (imna.vm_prov_year_status_zoek_gebied_klimaat s
     JOIN imna.zoek_gebied_klimaat a ON ((a.id = s.zoek_gebied_klimaat_id)));
;

CREATE OR REPLACE VIEW imna.v_rvo_zoek_gebied_water AS 
 SELECT ( SELECT dmn_provincie_code.code
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    s.subsidie_jaar,
    ( SELECT dmn_status_zoek_gebied_water.code
           FROM masterdata.dmn_status_zoek_gebied_water
          WHERE (dmn_status_zoek_gebied_water.id = s.status_id)) AS status,
    a.identificatie,
    a.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    a.begin_tijd,
    a.eind_tijd,
    ( SELECT dmn_natuur_type_water.code
           FROM masterdata.dmn_natuur_type_water
          WHERE (dmn_natuur_type_water.id = a.water_natuur_type_id)) AS water_natuur_type,
    a.naam,
    CASE
        WHEN (a.deelgebied_id IS NOT NULL) 
			THEN ( SELECT btrim((dmn_deelgebied.code)::text) AS btrim
					 FROM masterdata.dmn_deelgebied
					WHERE (dmn_deelgebied.id = a.deelgebied_id))
			ELSE NULL::text
    END AS deel_gebied,
    ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_functies_water fun
             JOIN masterdata.dmn_beheer_functie d ON ((d.id = fun.beheer_functie_id)))
          WHERE (fun.zoek_gebied_water_id = a.id)) AS toegestane_beheer_functies,
    ( SELECT string_agg((d.code)::text, ';'::text ORDER BY ((d.code)::text)) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_typen_water typ
             JOIN masterdata.dmn_beheer_type d ON ((d.id = typ.beheer_type_id)))
          WHERE (typ.zoek_gebied_water_id = a.id)) AS toegestane_beheer_typen,
    a.geom
   FROM (imna.vm_prov_year_status_zoek_gebied_water s
     JOIN imna.zoek_gebied_water a ON ((a.id = s.zoek_gebied_water_id)));
;
